create or replace function app.guard_document_version_update() returns trigger language plpgsql set search_path='' as $$begin if old.status='published' then if app.published_change_is_referential(to_jsonb(old),to_jsonb(new)) then return new;end if;raise exception 'Version % of document % is published and cannot be modified. Create a new version instead.',old.version_number,old.document_id using errcode='42501';end if;if new.status is distinct from old.status then if not app.publication_transition_allowed(old.status,new.status) then raise exception 'Publication status cannot move from % to %.',old.status,new.status using errcode='23514';end if;if not app.document_workflow_permission_allowed(new.status) then raise exception 'Missing permission for document version transition to %.',new.status using errcode='42501';end if;if new.status='approved' then if old.created_by=auth.uid() then raise exception 'Document version creator cannot approve the same version.' using errcode='42501';end if;new.approved_by:=auth.uid();new.approved_at:=now();end if;if new.status='published' then if new.approved_by is null then raise exception 'Approved actor is required before publication.' using errcode='23514';end if;if new.approved_by=auth.uid() then raise exception 'Document version approver cannot publish the same version.' using errcode='42501';end if;new.published_at:=coalesce(new.published_at,now());end if;elsif to_jsonb(new) is distinct from to_jsonb(old) and not app.has_permission('documents.update') then raise exception 'Missing documents.update permission.' using errcode='42501';end if;return new;end$$;
create or replace function app.guard_document_update() returns trigger language plpgsql set search_path='' as $$begin if old.status='published' then if new.status='archived' and current_setting('app.document_canonical_transition',true)='1' then if new.published_version_id is distinct from old.published_version_id or new.current_version_id is distinct from old.current_version_id or new.visibility is distinct from old.visibility or new.title is distinct from old.title or new.slug is distinct from old.slug or new.kind is distinct from old.kind or new.summary is distinct from old.summary or new.owner_admin_id is distinct from old.owner_admin_id then raise exception 'Published document content/identity is immutable during archive.' using errcode='42501';end if;new.archived_at:=coalesce(new.archived_at,now());return new;end if;raise exception 'Published document is immutable. Archive it through the canonical workflow and create a new version/document for changes.' using errcode='42501';end if;if new.status is distinct from old.status then if current_setting('app.document_canonical_transition',true)<>'1' then raise exception 'Document status transitions must use the canonical RPC.' using errcode='42501';end if;if not app.publication_transition_allowed(old.status,new.status) then raise exception 'Document status cannot move from % to %.',old.status,new.status using errcode='23514';end if;if not app.document_workflow_permission_allowed(new.status) then raise exception 'Missing permission for document transition to %.',new.status using errcode='42501';end if;if new.status='published' and new.published_version_id is distinct from new.current_version_id then raise exception 'A published document must publish its current version.' using errcode='23514';end if;elsif to_jsonb(new) is distinct from to_jsonb(old) and not app.has_permission('documents.update') then raise exception 'Missing documents.update permission.' using errcode='42501';end if;return new;end$$;
create or replace function app.guard_published_document_media_asset() returns trigger language plpgsql security definer set search_path='' as $$begin if exists(select 1 from public.document_versions dv where dv.file_asset_id=old.id and dv.status='published') then raise exception 'Media asset used by a published document version is immutable.' using errcode='42501';end if;return case when tg_op='DELETE' then old else new end;end$$;
drop trigger if exists published_document_media_asset_guard on public.media_assets;create trigger published_document_media_asset_guard before update or delete on public.media_assets for each row execute function app.guard_published_document_media_asset();revoke execute on function app.guard_published_document_media_asset() from public,anon,authenticated;
create or replace function app.transition_document_publication(p_document_id uuid,p_target public.publication_status) returns table(document_id uuid,title text,previous_status public.publication_status,status public.publication_status) language plpgsql security definer set search_path='' as $$declare v_document public.documents%rowtype;v_version public.document_versions%rowtype;v_required_permission text;begin v_required_permission:=case p_target when 'review' then 'documents.review' when 'approved' then 'documents.approve' when 'published' then 'documents.publish' when 'archived' then 'documents.archive' when 'draft' then 'documents.update' else null end;if v_required_permission is null or not app.has_permission(v_required_permission) then raise exception 'Permission denied.' using errcode='42501';end if;select d.* into v_document from public.documents d where d.id=p_document_id for update;if not found then raise exception 'Dokumen tidak ditemukan.' using errcode='P0002';end if;if not ((v_document.status='draft' and p_target='review') or (v_document.status='review' and p_target in('approved','draft')) or (v_document.status='approved' and p_target in('published','draft')) or (v_document.status='published' and p_target='archived')) then raise exception 'Transisi status dokumen tidak valid: % -> %.',v_document.status,p_target using errcode='22023';end if;if p_target<>'archived' then select dv.* into v_version from public.document_versions dv where dv.id=v_document.current_version_id and dv.document_id=v_document.id for update;if not found then raise exception 'Versi aktif dokumen tidak ditemukan.' using errcode='P0002';end if;end if;perform set_config('app.document_canonical_transition','1',true);if p_target='published' then if v_version.status<>'approved' then raise exception 'Versi aktif dokumen harus disetujui sebelum diterbitkan.' using errcode='22023';end if;if v_version.approved_by=auth.uid() then raise exception 'Document version approver cannot publish the same version.' using errcode='42501';end if;update public.document_versions set status='published' where id=v_version.id;update public.documents set status='published',published_version_id=v_version.id where id=v_document.id;elsif p_target='archived' then update public.documents set status='archived',archived_at=now() where id=v_document.id;else update public.document_versions set status=p_target where id=v_version.id;update public.documents set status=p_target,archived_at=null where id=v_document.id;end if;return query select v_document.id,v_document.title,v_document.status,p_target;end$$;